// 1. جلب النص الخارج من نود الـ Big Brain
const aiOutput = $('Big Brain').item.json.output || '';

// 2. تحديد مصدر الرسالة (واتساب أو تليجرام) بشكل آمن تماماً
let source = 'whatsapp'; 
try {
    if (($('Telegram Trigger') && $('Telegram Trigger').isExecuted) || 
        ($('Callback Query Trigger') && $('Callback Query Trigger').isExecuted)) {
        source = 'telegram';
    }
} catch (error) {
    // لو نودز التليجرام ما اشتغلتش في الـ Run الحالي، يثبت المصدر واتساب
    source = 'whatsapp';
}

// 3. إرجاع البيانات النظيفة للمصدر فوراً بدون تقسيم مسارات طبيب
return [{
    json: {
        output: aiOutput,
        source: source
    }
}];

// 1. جلب نص الاستجابة من الـ AI والمصدر
const aiResponse = $('Big Brain').item.json.output || "";
const source = $('Switch').item.json.source || "telegram";

// 2. تعيين قيم افتراضية فارغة
let patientName = "مريض غير مسجل";
let phone = "بدون هاتف";
let address = "لم يذكر";
let consultationType = "Clinic";
let cleanText = aiResponse; // افتراضياً النص النظيف هو النص كامل

try {
  // 3. البحث عن الـ JSON Block المخفي واستخراجه
  const jsonMatch = aiResponse.match(/\{[\s\S]*?\}/);

  if (jsonMatch) {
    const jsonBlock = JSON.parse(jsonMatch[0]);

    if (jsonBlock.patient_name) patientName = jsonBlock.patient_name.trim();
    if (jsonBlock.phone) phone = jsonBlock.phone.trim();
    if (jsonBlock.address) address = jsonBlock.address.trim();

    if (jsonBlock.consultation_type && jsonBlock.consultation_type.toLowerCase().includes('online')) {
      consultationType = "Online";
    }

    // 4. إزالة الـ JSON Block والـ Tag المخفي تماماً من الرسالة التي ستذهب للمريض
    cleanText = aiResponse
      .replace(/\{[\s\S]*?\}/g, "") // حذف بلوك الـ JSON
      .replace(/"booking_complete":\s*true/g, "") // حذف التاج
      .trim();
  }
} catch (error) {
  console.error("Error parsing AI JSON block:", error);
}

// 5. إخراج البيانات كاملة
return [{
  json: {
    patient_name: patientName,
    phone: phone,
    address: address,
    consultation_type: consultationType,
    source: source,
    clean_text: cleanText // هذا الحقل الذي ستقرأه نود التليجرام والواتساب
  }
}];

